namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, quantity, structure, and space." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and critical analysis." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." },
            new() { Id = 6, Code = "CHEM", Name = "Chemistry", Description = "Study of substances, their properties, and reactions." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering fundamental concepts including algorithms, data structures, and software engineering principles. Students will learn to think computationally and solve problems using programming.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and computational theory.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "In-depth study of data organization and algorithm design. Topics include linked lists, trees, graphs, sorting, searching, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is an award-winning researcher in theoretical computer science with publications in top-tier conferences. He has mentored dozens of graduate students.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Fundamentals of database design, SQL, normalization, transaction management, and modern NoSQL approaches. Includes a semester-long project building a complete database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd specializes in data management and has industry experience at leading tech companies. He brings practical insights into database architecture and design.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, CourseCode = "CS 450", Title = "Artificial Intelligence", Description = "Survey of AI techniques including search, knowledge representation, machine learning, natural language processing, and computer vision. Students complete hands-on projects using modern AI frameworks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and computational theory.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, derivatives, and their applications. Emphasis on problem-solving and mathematical reasoning.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is a distinguished professor of mathematics known for her contributions to abstract algebra and theoretical physics. She has received multiple teaching excellence awards.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss has over 20 years of experience in applied mathematics. His research spans numerical analysis and mathematical modeling.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world applications.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is a distinguished professor of mathematics known for her contributions to abstract algebra and theoretical physics. She has received multiple teaching excellence awards.", IsFeatured = false },

            // Physics
            new() { Id = 8, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational dynamics, and oscillatory motion with laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is renowned for his engaging teaching style and groundbreaking research in quantum electrodynamics. He has authored several popular science books.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, CourseCode = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and introduction to modern physics. Includes laboratory experiments and computational modeling.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a leading researcher in experimental physics with expertise in radiation and nuclear science. She has published extensively in peer-reviewed journals.", IsFeatured = false },

            // English
            new() { Id = 10, DepartmentId = 4, CourseCode = "ENG 101", Title = "College Composition", Description = "Development of academic writing skills including argumentation, research methods, citation practices, and revision strategies. Students produce a portfolio of polished essays.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Virginia Woolf", InstructorBio = "Dr. Woolf is an acclaimed author and literary scholar specializing in modernist literature. She brings creative writing expertise and a passion for narrative craft.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, CourseCode = "ENG 250", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods. Explores themes of identity, power, and human experience through close reading and discussion.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Virginia Woolf", InstructorBio = "Dr. Woolf is an acclaimed author and literary scholar specializing in modernist literature. She brings creative writing expertise and a passion for narrative craft.", IsFeatured = true },

            // History
            new() { Id = 12, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the late medieval period. Examines political, economic, social, and cultural developments across regions.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian and social activist whose work focuses on labor history, civil rights, and anti-war movements. He emphasizes primary source analysis in his teaching.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 5, CourseCode = "HIST 205", Title = "The Modern Era", Description = "Exploration of global history from the Enlightenment to the present, including revolutions, industrialization, world wars, and contemporary geopolitics.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian and social activist whose work focuses on labor history, civil rights, and anti-war movements. He emphasizes primary source analysis in his teaching.", IsFeatured = false },

            // Chemistry
            new() { Id = 14, DepartmentId = 6, CourseCode = "CHEM 101", Title = "General Chemistry I", Description = "Principles of chemistry including atomic structure, bonding, stoichiometry, states of matter, and thermochemistry. Weekly laboratory sessions reinforce lecture concepts.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 2:00–4:00 PM", InstructorName = "Dr. Linus Pauling", InstructorBio = "Dr. Pauling is a two-time Nobel laureate whose research spans chemical bonding, molecular biology, and orthomolecular medicine. He is passionate about undergraduate education.", IsFeatured = true },
            new() { Id = 15, DepartmentId = 6, CourseCode = "CHEM 201", Title = "Organic Chemistry", Description = "Study of carbon-containing compounds, reaction mechanisms, stereochemistry, and spectroscopic analysis. Essential for pre-medical and biochemistry students.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM + Lab Wed 2:00–4:00 PM", InstructorName = "Dr. Linus Pauling", InstructorBio = "Dr. Pauling is a two-time Nobel laureate whose research spans chemical bonding, molecular biology, and orthomolecular medicine. He is passionate about undergraduate education.", IsFeatured = false },
        };
    }

    public IReadOnlyList<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

