@page "/"
@using UniversityCourseCatalog.Services

@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the university course catalog. Browse departments, explore courses, and submit an enrollment request.</p>

<hr />

<h2>Featured Courses</h2>
<div class="row">
    @foreach (var course in featuredCourses)
    {
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@course.CourseCode</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                    <span class="badge bg-primary me-1">@course.Credits Credits</span>
                    <span class="badge bg-secondary">@Catalog.GetDepartmentName(course.DepartmentId)</span>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<hr />

<h2>Departments</h2>
<div class="row">
    @foreach (var dept in departments)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text text-muted">@dept.Description</p>
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">Browse @dept.Code Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private IReadOnlyList<UniversityCourseCatalog.Models.Course> featuredCourses = [];
    private IReadOnlyList<UniversityCourseCatalog.Models.Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetAllDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

